/// Get required workspace sizes for batch decode operation.
pub fn batch_decode_workspace_size(
    batch_size: i32,
    num_qo_heads: i32,
    num_kv_heads: i32,
    head_dim: i32,
    page_size: i32,
    max_seq_len: i32,
) -> Result<(usize, usize)> {
    let mut float_size: usize = 0;
    let mut int_size: usize = 0;

    let status = unsafe {
        flashinfer_batch_decode_workspace_size(
            &mut float_size,
            &mut int_size,
            batch_size,
            num_qo_heads,
            num_kv_heads,
            head_dim,
            page_size,
            max_seq_len,
        )
    };

    check_status(status)?;
    Ok((float_size, int_size))
}

