/// RAII wrapper for batch decode plan.
pub struct BatchDecodePlan {
    handle: FlashInferBatchDecodePlanHandle,
}

impl BatchDecodePlan {
    /// Create a new batch decode plan.
    ///
    /// # Arguments
    /// * `float_workspace` - GPU buffer for float workspace
    /// * `int_workspace` - GPU buffer for int workspace
    /// * `page_locked_workspace` - Page-locked host memory (optional, can be null)
    /// * `kv_indptr` - Cumulative page counts [batch_size + 1]
    /// * `batch_size` - Number of sequences
    /// * `num_qo_heads` - Number of query/output heads
    /// * `num_kv_heads` - Number of key/value heads
    /// * `head_dim` - Head dimension
    /// * `page_size` - Tokens per page
    /// * `dtype` - Data type
    /// * `pos_encoding` - Position encoding mode
    /// * `logits_soft_cap` - Soft cap for logits (0 to disable)
    /// * `window_left` - Sliding window size (-1 for full attention)
    /// * `enable_cuda_graph` - Whether this will run in a CUDA graph
    /// * `stream` - CUDA stream (raw pointer)
    #[allow(clippy::too_many_arguments)]
    pub unsafe fn new(
        float_workspace: *mut std::ffi::c_void,
        float_workspace_size: usize,
        int_workspace: *mut std::ffi::c_void,
        int_workspace_size: usize,
        page_locked_workspace: *mut std::ffi::c_void,
        page_locked_size: usize,
        kv_indptr: *const i32,
        batch_size: i32,
        num_qo_heads: i32,
        num_kv_heads: i32,
        head_dim: i32,
        page_size: i32,
        dtype: DType,
        pos_encoding: PosEncoding,
        logits_soft_cap: f32,
        window_left: i32,
        enable_cuda_graph: bool,
        stream: *mut std::ffi::c_void,
    ) -> Result<Self> {
        let mut handle: FlashInferBatchDecodePlanHandle = ptr::null_mut();

        let status = flashinfer_batch_decode_plan(
            &mut handle,
            float_workspace,
            float_workspace_size,
            int_workspace,
            int_workspace_size,
            page_locked_workspace,
            page_locked_size,
            kv_indptr,
            batch_size,
            num_qo_heads,
            num_kv_heads,
            head_dim,
            page_size,
            dtype.into(),
            pos_encoding.into(),
            logits_soft_cap,
            window_left,
            enable_cuda_graph as i32,
            stream,
        );

        check_status(status)?;
        Ok(Self { handle })
    }

    /// Execute batch decode with this plan.
    #[allow(clippy::too_many_arguments)]
    pub unsafe fn run(
        &self,
        q: *const std::ffi::c_void,
        k_cache: *const std::ffi::c_void,
        v_cache: *const std::ffi::c_void,
        kv_indptr: *const i32,
        kv_indices: *const i32,
        kv_last_page_len: *const i32,
        output: *mut std::ffi::c_void,
        lse: *mut f32,
        kv_layout: KVLayout,
        stream: *mut std::ffi::c_void,
    ) -> Result<()> {
        let status = flashinfer_batch_decode_run(
            self.handle,
            q,
            k_cache,
            v_cache,
            kv_indptr,
            kv_indices,
            kv_last_page_len,
            output,
            lse,
            kv_layout.into(),
            stream,
        );

        check_status(status)
    }
}

impl Drop for BatchDecodePlan {
    fn drop(&mut self) {
        unsafe {
            flashinfer_batch_decode_plan_destroy(self.handle);
        }
    }
}

// BatchDecodePlan is Send but not Sync (single-threaded use)
unsafe impl Send for BatchDecodePlan {}

